// AD1204U Mi BLE/MIOT adaptation. Protocol and typed-property layout verified
// against zuyan9/ha-cuk-ble (Apache-2.0); see licenses/cuktech-NOTICE.txt.
namespace Charker;
internal static class CuktechProtocol {
 public const string Model="AD1204U";
 public static byte[] Hex(string s)=>Convert.FromHexString(s);
 public static byte[] Token(string s){s=string.Concat(s.Where(c=>!char.IsWhiteSpace(c)));if(s.Length==32)s=s[..24];if(s.Length!=24)throw new ArgumentException("Token 应为 24 位十六进制字符（12 字节）");try{return Hex(s);}catch(FormatException){throw new ArgumentException("Token 包含无效字符");}}
 public static ulong Address(string s){s=s.Replace(":","").Replace("-","").Trim();if(s.Length!=12||!ulong.TryParse(s,System.Globalization.NumberStyles.HexNumber,null,out var a)||a==0)throw new ArgumentException("请输入有效的蓝牙 MAC 地址");return a;}
 public static string Mac(ulong a)=>string.Join(":",a.ToString("X12").Chunk(2).Select(x=>new string(x)));
 public static bool Advertisement(string name,IEnumerable<byte[]> sections)=>name.Equals("njcuk.fitting.ad1204",StringComparison.OrdinalIgnoreCase)||sections.Any(b=>b.Length>=6&&b[0]==0x95&&b[1]==0xfe&&b[4]==0x0e&&b[5]==0x66);
 public static byte[] Derive(byte[] token,byte[] appRandom,byte[] deviceRandom)=>HKDF.DeriveKey(HashAlgorithmName.SHA256,token,64,appRandom.Concat(deviceRandom).ToArray(),Encoding.ASCII.GetBytes("mible-login-info"));
 public static byte[] Nonce(byte[] iv,int counter){if(iv.Length!=4||counter is <0 or >65535)throw new CryptographicException("蓝牙会话计数已到上限，请重新连接");var n=new byte[12];iv.CopyTo(n,0);BitConverter.GetBytes(counter).CopyTo(n,8);return n;}
 public static byte[] Encrypt(byte[] key,byte[] iv,int counter,byte[] plain){var b=new byte[plain.Length+4];using var aes=new AesCcm(key);aes.Encrypt(Nonce(iv,counter),plain,b.AsSpan(0,plain.Length),b.AsSpan(plain.Length,4));return b;}
 public static byte[] Decrypt(byte[] key,byte[] iv,int counter,byte[] cipher){if(cipher.Length<4)throw new InvalidDataException("加密蓝牙数据过短");var b=new byte[cipher.Length-4];using var aes=new AesCcm(key);aes.Decrypt(Nonce(iv,counter),cipher.AsSpan(0,b.Length),cipher.AsSpan(b.Length,4),b);return b;}
 public static byte[] Get(ushort seq,int[] ids){if(ids.Length>32)throw new ArgumentOutOfRangeException(nameof(ids));return new byte[]{checked((byte)(6+3*ids.Length)),0x20,(byte)seq,(byte)(seq>>8),2,(byte)ids.Length}.Concat(ids.SelectMany(p=>new byte[]{2,(byte)p,(byte)(p>>8)})).ToArray();}
 public static byte[] Set(ushort seq,int id,int value,int size=1,bool boolean=false){if(size is not (1 or 2 or 4)||value<0||(size==1&&value>255)||(size==2&&value>65535))throw new ArgumentOutOfRangeException(nameof(value));return new byte[]{(byte)(11+size),0x20,(byte)seq,(byte)(seq>>8),0,1,2,(byte)id,(byte)(id>>8),(byte)size,(byte)(boolean?0:size==4?0x50:size==2?0x20:0x10)}.Concat(BitConverter.GetBytes(value).Take(size)).ToArray();}
 internal record Property(int Id,uint Value);
 public static Property[] Parse(byte[] b){if(b.Length<6||b[1]!=0x20||b[0]!=(byte)(b.Length&255))throw new InvalidDataException("无效 MIOT 响应");bool status=b[4]==3;if(!status&&b[4]!=4)return [];int pos=6;var result=new List<Property>();for(int n=0;n<b[5];n++){int prefix=status?7:5;if(pos+prefix>b.Length)throw new InvalidDataException("MIOT 属性不完整");int siid=b[pos],id=BitConverter.ToUInt16(b,pos+1),error=status?BitConverter.ToUInt16(b,pos+3):0,size=b[pos+(status?5:3)];if(size is not (1 or 2 or 4)||pos+prefix+size>b.Length)throw new InvalidDataException("MIOT 属性类型或长度无效");uint value=0;for(int i=0;i<size;i++)value|=(uint)b[pos+prefix+i]<<(8*i);if(siid==2&&error==0)result.Add(new(id,value));pos+=prefix+size;}if(pos!=b.Length)throw new InvalidDataException("MIOT 响应含多余字节");return result.ToArray();}
 public static void Apply(DeviceState s,Property[] properties){lock(s.Sync){bool telemetry=false;foreach(var item in properties){uint v=item.Value;if(item.Id is >=1 and <=4){var p=s.Ports[item.Id-1];p.Status=(int)(v&255);p.Voltage=((v>>24)&255)/10.0;p.Current=((v>>16)&255)/10.0;p.Power=p.Status==0||p.On==false?0:Math.Round(p.Voltage*p.Current,2);p.CableAttached=p.Status!=0;int code=(int)((v>>8)&255);p.Protocol=p.Status==0?null:code switch{8=>"PD PPS",0x0a=>"PD Fixed",0x60=>"USB-A",0x70=>"QC",1 or 3 or 4 or 5 or 6 or 7 or 0x30 or 0x80=>"USB PD",_=>$"协议 0x{code:X2}"};telemetry=true;}else{string? key=item.Id switch{5=>"mode",6=>"timeout",7=>"protocolControl",13=>"language",15=>"usbAlwaysOn",16=>"portMask",19=>"idleScreen",20=>"directionLock",21=>"protocolExtend",_=>null};if(key!=null)s.Settings[key]=(int)v;if(item.Id==16)for(int i=0;i<4;i++){s.Ports[i].On=(v&(1<<i))!=0;if(s.Ports[i].On==false)s.Ports[i].Power=0;}}}if(telemetry){s.Updated=DateTimeOffset.UtcNow;s.Status="已连接";}}}
}
